// NORMALIZE URL: clean the URL from the form and extract the domain (no URL() needed)
const input = $input.first().json;
const raw = String(input['Company URL'] || '').trim();
const m = raw.match(/^(?:https?:\/\/)?([^\/?#:\s]+)(?::\d+)?/i);
if (!m || !m[1].includes('.')) throw new Error('Invalid URL: ' + raw);
const host = m[1].toLowerCase();
const domain = host.replace(/^www\./, '');
const run_id = 'run_' + Date.now();

return [{ json: {
  run_id,
  input_url: 'https://' + host,
  domain,
  notes: input['Notes'] || '',
  focus_market: input['Focus market'] || '',
  include_global: (input['Include global players'] || 'Yes') === 'Yes'
} }];

// NODE 8 - CHECK QUOTES: parse the AI Agent output and verify every quote against the source text.
// Single fields: one quote. List fields: one quote PER ITEM; unproven items are dropped one by one.
const base = $('Build prompt').first().json;
const raw = String($input.first().json.output || '').trim();
// Take the JSON object out of any code fence, then parse. If that fails, repair the most
// common model mistake (a trailing comma before } or ]) and try once more.
const jsonText = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
let profile, repaired = false;
try {
  profile = JSON.parse(jsonText);
} catch (e1) {
  try {
    profile = JSON.parse(jsonText.replace(/,\s*([}\]])/g, '$1'));
    repaired = true;
  } catch (e2) {
    throw new Error('AI Agent did not return valid JSON (' + e2.message + '): ' + raw.slice(0, 300));
  }
}

const norm = s => String(s || '').toLowerCase()
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-')
  .replace(/[*_#>`\[\]()|]/g, ' ').replace(/\s+/g, ' ').trim();
const corpus = norm(base.fetched_text);
const isProven = q => { const n = norm(q); return n.length >= 8 && corpus.includes(n); };

const fields = {};
const clean = {};
let verified = 0, partial = 0, rejected = 0, missing = 0;

for (const [field, obj] of Object.entries(profile)) {
  const v = obj ? obj.value : null;

  // List field with one quote per item
  if (Array.isArray(v) && v.some(x => x && typeof x === 'object')) {
    const kept = [], dropped = [];
    for (const it of v) {
      if (it && it.item && isProven(it.quote)) kept.push({ item: it.item, quote: it.quote, source_url: it.source_url || null });
      else dropped.push({ item: it && it.item, quote: it && it.quote });
    }
    clean[field] = { value: kept.map(k => k.item), items: kept, dropped_items: dropped };
    if (!v.length) { fields[field] = 'empty'; missing++; }
    else if (!kept.length) { fields[field] = 'rejected'; rejected++; }
    else if (dropped.length) { fields[field] = 'partial (' + kept.length + '/' + v.length + ')'; partial++; }
    else { fields[field] = 'verified'; verified++; }
    continue;
  }

  // Empty single field or empty list
  const isEmpty = v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
  if (isEmpty) { fields[field] = 'empty'; missing++; clean[field] = { value: null, quote: null, source_url: null }; continue; }

  // Single field (or an old-style list of strings with one quote)
  if (isProven(obj.quote)) {
    fields[field] = 'verified'; verified++;
    clean[field] = { value: v, quote: obj.quote, source_url: obj.source_url || null };
  } else {
    fields[field] = 'rejected'; rejected++;
    clean[field] = { value: null, quote: null, source_url: null, rejected_value: v, rejected_quote: obj.quote || null };
  }
}

const val = f => (clean[f] ? clean[f].value : null);
const cap = (s, n) => (s.length > n ? s.slice(0, n) + '\n[truncated]' : s);   // Airtable long text limit
return [{ json: {
  run_id: base.run_id,
  input_url: base.input_url,
  domain: base.domain,
  company_name: val('company_name'),
  legal_entity: val('legal_entity'),
  hq_city: val('hq_city'),
  category: val('category'),
  notes: base.notes,
  profile_json: JSON.stringify(clean, null, 2),
  quote_check_json: JSON.stringify(fields, null, 2),
  verified, partial, rejected, empty: missing,
  sources_json: JSON.stringify(base.pages, null, 2),
  dropped_json: JSON.stringify(base.dropped, null, 2),
  fetched_text: cap(base.fetched_text, 95000),
  json_repaired: repaired,
  status: 'profile_ready'
} }];

// NODE 4 - SORT SOURCES: rank Perplexity results, drop noise, decide if pages need fetching
const base = $('Normalize URL').first().json;
const results = $input.first().json.results || [];

const MAX_TOTAL = 40000;   // total characters sent to the AI
const MAX_PER_PAGE = 12000;
const MIN_CORE = 3000;     // below this, the core pages are too thin -> fetch them
const LIMITS = { blog: 2, legal: 1, other: 2 };

const pathOf = url => {
  const m = String(url).match(/^https?:\/\/[^\/?#]+([^?#]*)/i);
  return (m ? m[1] : '/').toLowerCase().replace(/\/+$/, '') || '/';
};

function classify(url) {
  const p = pathOf(url);
  if (/\/llms(-full)?\.txt$/.test(p)) return { type: 'llms', priority: 1 };
  if (p === '/' || /^\/[a-z]{2}(-[a-z]{2})?$/.test(p)) return { type: 'home', priority: 1 };
  if (/privacy|datenschutz|cookie/.test(p)) return { type: 'privacy', priority: 99 };
  if (/imprint|impressum|terms|agb|legal/.test(p)) return { type: 'legal', priority: 4 };
  if (/^(\/[a-z]{2})?\/(blog|news|insights|resources|magazin)$/.test(p)) return { type: 'blog_index', priority: 99 };
  if (/blog|news|article|insight|resource|post|magazin/.test(p)) return { type: 'blog', priority: 3 };
  if (/about|company|team|ueber-uns|uber-uns|unternehmen/.test(p)) return { type: 'about', priority: 2 };
  if (/pricing|preise|plans/.test(p)) return { type: 'pricing', priority: 2 };
  if (/customer|case-stud|kunden|referen/.test(p)) return { type: 'customers', priority: 2 };
  if (/product|platform|solution|feature|produkt|loesung|losung/.test(p)) return { type: 'product', priority: 2 };
  if (/career|jobs|karriere/.test(p)) return { type: 'careers', priority: 2 };
  return { type: 'other', priority: 3 };
}

const seen = new Set();
const candidates = [];
const dropped = [];
for (const r of results) {
  if (!r || !r.url) continue;
  const key = String(r.url).toLowerCase().replace(/\/+$/, '');
  if (seen.has(key)) { dropped.push({ url: r.url, reason: 'duplicate' }); continue; }
  seen.add(key);
  const c = classify(r.url);
  if (c.priority === 99) { dropped.push({ url: r.url, reason: c.type === 'blog_index' ? 'blog index page' : 'privacy page' }); continue; }
  candidates.push({
    page_type: c.type, priority: c.priority, page_url: r.url, title: r.title || '',
    date: r.date || r.last_updated || '', text: String(r.snippet || '').trim()
  });
}

// keep only one home page (language variants like /de count as home too)
const homes = candidates.filter(c => c.page_type === 'home');
for (const extra of homes.slice(1)) { extra.skip = 'second home page (language variant)'; }

// order: priority, then newest first inside the same priority
candidates.sort((a, b) => a.priority - b.priority || String(b.date).localeCompare(String(a.date)));

const counts = {};
const pages = [];
let total = 0;
for (const c of candidates) {
  if (c.skip) { dropped.push({ url: c.page_url, reason: c.skip }); continue; }
  const limit = LIMITS[c.page_type];
  counts[c.page_type] = (counts[c.page_type] || 0) + 1;
  if (limit && counts[c.page_type] > limit) { dropped.push({ url: c.page_url, reason: c.page_type + ' limit (' + limit + ')' }); continue; }
  if (!c.text) { dropped.push({ url: c.page_url, reason: 'empty snippet' }); continue; }
  const text = c.text.slice(0, MAX_PER_PAGE);
  if (total + text.length > MAX_TOTAL) { dropped.push({ url: c.page_url, reason: 'text budget full' }); continue; }
  total += text.length;
  pages.push({ page_type: c.page_type, priority: c.priority, page_url: c.page_url, title: c.title, source: 'perplexity_snippet', text });
}

const coreChars = pages.filter(p => p.priority <= 2).reduce((n, p) => n + p.text.length, 0);
const needs_fetch = coreChars < MIN_CORE;
let fetch_urls = [];
if (needs_fetch) {
  fetch_urls = candidates.filter(c => c.priority <= 2).map(c => c.page_url).slice(0, 5);
  if (!fetch_urls.length) fetch_urls = [base.input_url];
}

return [{ json: {
  ...base,
  pages,
  page_summary: pages.map(p => p.page_type + ': ' + p.page_url + ' (' + p.text.length + ' chars)'),
  dropped,
  core_chars: coreChars,
  total_chars: total,
  needs_fetch,
  fetch_urls
} }];

// NODE 6 - BUILD PROMPT: combines snippet pages (+ fetched pages if any) and builds the AI prompt.
// Both IF outputs connect here; only one of them runs per company.
const sorted = $('Sort sources').first().json;
const strip = u => String(u || '').toLowerCase().replace(/\/+$/, '');

// 1. Start from the pages chosen by Sort sources
const pages = (sorted.pages || []).map(p => ({ ...p }));

// 2. Add fetched pages (only present on the "needs fetch" path); full text replaces a snippet of the same URL
for (const it of $input.all()) {
  const j = it.json || {};
  const url = j.url || (j['#debug'] && j['#debug'].url);
  const text = String(j.markdown || j.text || '').trim();
  if (!url || !text || j.pages) continue;   // skip the Sort sources item itself
  const existing = pages.find(p => strip(p.page_url) === strip(url));
  if (existing) { existing.text = text; existing.source = 'fetched'; }
  else pages.push({ page_type: 'fetched', priority: 2, page_url: url, title: j.title || '', source: 'fetched', text });
}

if (!pages.length) throw new Error('No source text for ' + sorted.input_url + ' (search and fetch both empty)');

// 3. Wrap each page with its URL and type
const MAX_PER_PAGE = 12000;
const fetched_text = pages
  .map(p => '<page url="' + p.page_url + '" type="' + p.page_type + '">\n' + String(p.text).slice(0, MAX_PER_PAGE) + '\n</page>')
  .join('\n\n');

const system_prompt = [
  "You extract a company profile from text taken from the company's own website.",
  'Return ONLY one JSON object. No markdown, no code fences, no commentary.',
  '',
  'Single fields: return {"value": "...", "quote": "...", "source_url": "..."}',
  'List fields (marked "list"): return {"value": [{"item": "...", "quote": "...", "source_url": "..."}, ...]}',
  '- Every list item has its OWN quote that proves that item. Leave out any item you cannot prove with a quote.',
  '- "quote" is copied word for word from the page text (max 30 words). Never paraphrase or fix it.',
  '- "source_url" is the url attribute of the <page> the quote comes from.',
  '- If the pages do not state it, return {"value": null, "quote": null, "source_url": null}. For a list, return {"value": []}.',
  '- The value must follow directly from its quote. Never guess and never use outside knowledge about the company.',
  '- Write values in English. Keep quotes in the original language of the page.',
  '',
  'Source rules:',
  '- Page types llms, home, about, product, pricing, customers, careers and fetched are the company describing itself: use them for all fields.',
  '- Page type blog: use only for differentiators and integrations_tech. Never take customers, numbers or results from a blog: blogs quote statistics and case studies about OTHER companies.',
  '- Page type legal: use only for legal_entity and hq_city.',
  '- Ignore sample dashboards, demo data and example numbers in product screenshots.',
  '- "Industries served" or "who we serve" lists describe buyers, not customers.',
  '- regions = countries or markets the company sells to. Hosting location, data location or office address is NOT a region.',
  '',
  'Fields:',
  'company_name: the brand name',
  'legal_entity: the registered company name (e.g. "Example GmbH")',
  'hq_city: city of the headquarters',
  'one_liner: what the company does, in one sentence',
  'category: the software or service category in 2-5 words (e.g. "freight audit software")',
  'offering (list): the products or services it sells',
  'problem_solved: the customer problem it solves',
  'buyer_industries (list): industries of its customers',
  'buyer_company_size: size of its customers (e.g. SMB, mid-market, enterprise)',
  'buyer_roles (list): job roles that buy or use it',
  'pricing_model: e.g. subscription per seat, usage-based, project-based, custom quote',
  'price_level: one of free, low, mid, high, enterprise',
  'regions (list): countries or regions it serves',
  'named_customers (list): companies named as customers',
  'differentiators (list): what it claims makes it different',
  'integrations_tech (list): integrations, platforms and technologies it mentions',
  'size_stage_hints: founding year, team size, funding or stage'
].join('\n');

const user_prompt = 'Company website: ' + sorted.input_url + '\n\n' + fetched_text;

return [{ json: {
  run_id: sorted.run_id,
  input_url: sorted.input_url,
  domain: sorted.domain,
  notes: sorted.notes,
  pages: pages.map(p => ({ page_type: p.page_type, page_url: p.page_url, source: p.source, chars: String(p.text).length })),
  dropped: sorted.dropped || [],
  fetched_text,
  system_prompt,
  user_prompt
} }];
